def lps(s: str) -> int:
    def dp(s, i, j, memo):
        if i > j:
            return 0
        if i == j:
            return 1
        if (i, j) in memo:
            return memo[(i, j)]
        if s[i] == s[j]:
            memo[(i, j)] = 2 + dp(s, i + 1, j - 1, memo)
        else:
            memo[(i, j)] = max(dp(s, i + 1, j, memo), dp(s, i, j - 1, memo))
        return memo[(i, j)]

    return dp(s, 0, len(s) - 1, {})

